def alspachWolfeWindowMeasures (M : JLMS.AtomicDualModel 𝕜 K) (ε : ℝ)
    (B : Set (WeakDual 𝕜 (JLMS.CZero 𝕜 K))) (C : Set K) (α : Ordinal) :
    Set (WeakDual 𝕜 (JLMS.CZero 𝕜 K)) :=
  {μ | ∃ U ⊆ C, (μ, U) ∈ wolfeFamily M ε B α}

